$ErrorActionPreference = "Stop"
$ROOT = "C:\Users\santi\OneDrive\Escritorio\ALPHA_ENGINE_PRODUCTION"
$REC  = Join-Path $ROOT "ALPHA_ENGINE_DATA_RECOVERY_V1"
$V13  = Join-Path $ROOT "ALPHA_ENGINE_V13_RETURN_FIRST_MULTI_HORIZON"
$WEB  = Join-Path $ROOT "web\v4"
$SERVER = Join-Path $WEB "run_alpha_engine_v4.py"
$APP = Join-Path $WEB "app.js"
$SMOKE = Join-Path $REC "scripts\smoke_v41.py"
$CATCH = Join-Path $REC "scripts\catchup_v41.py"
$LOG = Join-Path $REC "outputs\data_recovery_v1\web_v41_runtime.log"

Write-Host ""
Write-Host "================================================================"
Write-Host "ALPHA ENGINE V4.1 - LIVE COMPLETION"
Write-Host "MARKET VALUES + LIVE PULSE + AUTO FORWARD + EXCEL MIRROR"
Write-Host "NO LLM / NO SHEETS / NO V13 PARAMETER MUTATION"
Write-Host "================================================================"

if (-not (Test-Path $ROOT)) { throw "ROOT missing: $ROOT" }
if (-not (Test-Path $SERVER)) { throw "V4 server missing. Run FINAL_ALPHA_ENGINE_V4.ps1 first." }

function Write-B64File([string]$Path,[string]$B64) {
  [IO.File]::WriteAllBytes($Path,[Convert]::FromBase64String($B64))
}

Write-Host ""
Write-Host "[1/8] V13 IMMUTABILITY SNAPSHOT"
$critical = @(
  "outputs\v13_phase2r_model_spec.json",
  "outputs\v13_phase2u_expert_evidence.csv",
  "outputs\v13_phase3aa_freeze_manifest.json",
  "outputs\v13_phase4_sealed_features.csv",
  "outputs\v13_phase4_model_seal_manifest.json",
  "outputs\v13_phase4_sealed_model_bundle.joblib"
)
$before = @{}
foreach($rel in $critical) {
  $p=Join-Path $V13 $rel
  if(-not(Test-Path $p)){throw "Critical V13 file missing: $p"}
  $before[$rel]=(Get-FileHash -Algorithm SHA256 $p).Hash
}
Write-Host "  PASS"

Write-Host ""
Write-Host "[2/8] BACKUP CURRENT V4"
$stamp=Get-Date -Format "yyyyMMdd_HHmmss"
$backup=Join-Path $REC "outputs\data_recovery_v1\web_backups\v41_$stamp"
New-Item -ItemType Directory -Force -Path $backup | Out-Null
Copy-Item $SERVER (Join-Path $backup "run_alpha_engine_v4.py") -Force
Copy-Item $APP (Join-Path $backup "app.js") -Force
Write-Host "  PASS $backup"

Write-Host ""
Write-Host "[3/8] INSTALL V4.1"
Write-B64File $SERVER ""
Write-B64File $APP ""
Write-B64File $SMOKE ""
Write-B64File $CATCH ""
python -m py_compile $SERVER $SMOKE $CATCH
if($LASTEXITCODE -ne 0){throw "Python syntax validation failed"}
Write-Host "  PASS"

Write-Host ""
Write-Host "[4/8] STOP ONLY ALPHA V4 SERVER"
$listeners=@(Get-NetTCPConnection -LocalPort 8765 -State Listen -ErrorAction SilentlyContinue)
foreach($l in $listeners){
  $proc=Get-CimInstance Win32_Process -Filter "ProcessId=$($l.OwningProcess)" -ErrorAction SilentlyContinue
  if($proc -and $proc.CommandLine -like "*run_alpha_engine_v4.py*"){
    Stop-Process -Id $l.OwningProcess -Force -ErrorAction Stop
    Write-Host "  stopped PID=$($l.OwningProcess)"
  } else {
    throw "Port 8765 is occupied by another process. Nothing was killed."
  }
}
Start-Sleep -Milliseconds 700
Write-Host "  PASS"

Write-Host ""
Write-Host "[5/8] START V4.1"
New-Item -ItemType Directory -Force -Path (Split-Path $LOG -Parent) | Out-Null
# Use cmd redirection because Start-Process cannot redirect stdout+stderr to the same file.
$cmd = '/c python "' + $SERVER + '" >> "' + $LOG + '" 2>&1'
$launcher=Start-Process -FilePath "cmd.exe" -ArgumentList $cmd -WindowStyle Hidden -PassThru
Write-Host "  launcher PID=$($launcher.Id)"

Write-Host ""
Write-Host "[6/8] FULL WEB + MARKET + EXCEL SMOKE"
python $SMOKE
if($LASTEXITCODE -ne 0){throw "V4.1 smoke failed. V13 remains untouched."}

Write-Host ""
Write-Host "[7/8] FORWARD CATCH-UP TO LATEST COMPLETED US SESSION"
python $CATCH
if($LASTEXITCODE -ne 0){
  Write-Host ""
  Write-Host "Forward did not catch up. Web/market/Excel fixes remain installed."
  Write-Host "See: $LOG"
  throw "V4.1 forward catch-up failed. V13 sealed core remains untouched."
}

Write-Host ""
Write-Host "[8/8] V13 IMMUTABILITY VERIFY"
foreach($rel in $critical){
  $p=Join-Path $V13 $rel
  $after=(Get-FileHash -Algorithm SHA256 $p).Hash
  if($after -ne $before[$rel]){throw "V13 MUTATION DETECTED: $rel"}
}
Write-Host "  PASS 6/6 byte-identical"

Write-Host ""
Write-Host "================================================================"
Write-Host "ALPHA ENGINE V4.1: PASS"
Write-Host "================================================================"
Write-Host "MARKET TABLE         : NORMALIZED 41-COL DR1 PAYLOAD"
Write-Host "MARKET PULSE         : LIVE REGULAR SESSION / 6 BENCHMARKS"
Write-Host "MARKET REFRESH       : WORKING + VALIDATED"
Write-Host "FORWARD              : AUTO-CATCH-UP + 5 MIN WATCHDOG"
Write-Host "FORWARD BUTTON       : BACKGROUND JOB + STATUS"
Write-Host "EXCEL                : AlphaEngine_Cartera_Real.xlsx"
Write-Host "EXCEL SHEETS         : Operaciones / Posiciones / Resumen / Mercado / Fundamentales / Forward"
Write-Host "LEGACY ANALIZADOR    : NOT USED"
Write-Host "LLM                  : PAUSED"
Write-Host "V13 SEALED CORE      : UNCHANGED"
Write-Host "================================================================"
Start-Process "http://127.0.0.1:8765/"
